from _veri_kaynak import *
from _gzlib import takvim

def M(t, b, tur, taraflar, yer, d, kaynak, gun, kesinlik, ic_not=None, gz=None, onem=3, dunya=1, etiket=None):
    m = {'t': t, 'b': b, 'tur': tur, 'onem': onem, 'dunya': dunya, 'kapsam': 'ic',
         'etiket': etiket or ['konu-siyasi'], 'yer': yer, 'taraflar': taraflar, 'd': d, 'kaynak': kaynak,
         'gun': gun, 'kesinlik': kesinlik}
    if ic_not: m['ic_not'] = ic_not
    if gz: m['ic_not_takvim'] = takvim(t, gz)
    return m

